public struct CustomDuelResource
{
    public ushort LP;
    public byte SummonPower;
    public byte SummonRecharge;
    public byte StartingCol;
    public byte StartingRow;
    public ushort Zoom;
    

    public static byte[] GetBytesFromResource(CustomDuelResource[] resources)
    {
        byte[] bytes = new byte[resources.Length * 8];

        for (int i = 0; i < resources.Length; i++)
        {
            int offset = i * 8;

            BitConverter.GetBytes(resources[i].LP).CopyTo(bytes, offset + 0);
            bytes[offset + 2] = resources[i].SummonPower;
            bytes[offset + 3] = resources[i].SummonRecharge;
            bytes[offset + 4] = resources[i].StartingCol;
            bytes[offset + 5] = resources[i].StartingRow;
            BitConverter.GetBytes(resources[i].Zoom).CopyTo(bytes,offset+6);
            
        }

        return bytes;
    }

   
    public static CustomDuelResource[] CreateResourcesFromBytes(byte[] bytes)
    {
        if (bytes.Length % 8 == 0)
        {
            int size = bytes.Length / 8;
            CustomDuelResource[] customDuelResources = new CustomDuelResource[size];
            for (int i = 0; i < size; i++)
            {
                int customResourceTableIndex = i * 8;

                customDuelResources[i].LP = BitConverter.ToUInt16(bytes, customResourceTableIndex);
                customDuelResources[i].SummonPower = bytes[customResourceTableIndex + 2];
                customDuelResources[i].SummonRecharge = bytes[customResourceTableIndex + 3];
                customDuelResources[i].StartingCol = bytes[customResourceTableIndex + 4];
                customDuelResources[i].StartingRow = bytes[customResourceTableIndex + 5];
                customDuelResources[i].Zoom = BitConverter.ToUInt16(bytes,customResourceTableIndex + 6);
                
            }
            return customDuelResources;
        }
        else
        {
            throw new Exception("Not correct amount of bytes, probably reading from wrong place");
        }
    }

    public static void SetDefaultCustomResource(ref CustomDuelResource resource, int side)
    {
        resource.LP = 4000;
        resource.SummonPower = 4;
        resource.SummonRecharge = 3;
        resource.Zoom = 200;
        if (side == 0)
        {
            resource.StartingCol = 3;
            resource.StartingRow = 6;
        }
        else
        {
            resource.StartingCol = 3;
            resource.StartingRow = 0;
        }
    }
}